reproduction.script:
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {mkdir, writeFile, readFile, realpath} from 'node:fs/promises';
import {join} from 'node:path';
import {pathToFileURL} from 'node:url';
const [dev, temporary] = process.argv.slice(2), root = await realpath(temporary);
const {GitWorkspaces} = await import(pathToFileURL(join(dev, 'src/workspaces.ts')).href);
const git = (cwd, ...args) => execFileSync('git', [
  '-c', 'user.name=R06 Fixture', '-c', 'user.email=fixture@localhost',
  '-c', 'core.hooksPath=/dev/null', '-c', 'commit.gpgsign=false', ...args
], {cwd, encoding:'utf8', stdio:['ignore','pipe','pipe']}).trim();
async function fixture(name, ignored = false) {
  const dir = join(root, name), repo = join(dir, 'repo');
  await mkdir(repo, {recursive:true}); git(repo, 'init', '-b', 'main');
  await writeFile(join(repo, 'base.txt'), 'base\n');
  await writeFile(join(repo, 'other.txt'), 'other\n');
  if (ignored) await writeFile(join(repo, '.gitignore'), 'cache/\n');
  git(repo, 'add', '.'); git(repo, 'commit', '-m', 'base');
  return {repo, manager:new GitWorkspaces('run-'+name, join(dir, 'run'))};
}
for (const mode of ['ignored-nested','unignored-nested','ignored-regular']) {
  const {repo, manager} = await fixture(mode, mode !== 'unignored-nested');
  const initial = git(repo, 'rev-parse', 'HEAD');
  const a = await manager.allocate(repo, 'candidate');
  await mkdir(join(a.path, 'cache'));
  await writeFile(join(a.path, 'cache/value.txt'), 'WORKER\n');
  git(a.path, 'add', '-f', 'cache/value.txt'); const source = await manager.commit(a);
  const cache = join(repo, 'cache'); await mkdir(cache);
  if (mode !== 'ignored-regular') {
    git(cache, 'init', '-b', 'local');
    await writeFile(join(cache, 'value.txt'), 'LOCAL COMMITTED BASE\n');
    git(cache, 'add', '.'); git(cache, 'commit', '-m', 'local base');
  }
  await writeFile(join(cache, 'value.txt'), 'UNCOMMITTED USER DATA\n');
  const ignored = git(repo, 'ls-files', '--others', '--ignored', '--exclude-standard', '-z')
    .split('\0').filter(Boolean);
  let result, error;
  try { result = await manager.integrate(repo, [source], [source]); }
  catch (e) { error = e.message; }
  const disk = await readFile(join(cache, 'value.txt'), 'utf8');
  if (mode === 'ignored-nested') {
    assert.ok(result); assert.equal(disk, 'WORKER\n');
    assert.notEqual(git(repo, 'rev-parse', 'HEAD'), initial);
    assert.equal(git(cache, 'show', 'HEAD:value.txt'), 'LOCAL COMMITTED BASE');
  } else {
    assert.ok(error); assert.equal(disk, 'UNCOMMITTED USER DATA\n');
    assert.equal(git(repo, 'rev-parse', 'HEAD'), initial);
  }
  console.log(JSON.stringify({id:'r06-B01', mode, ignored,
    success:!!result, uncommittedUserDataLost:disk !== 'UNCOMMITTED USER DATA\n'}));
}
for (const flag of ['assume-unchanged','skip-worktree']) {
  const {repo, manager} = await fixture(flag);
  git(repo, 'update-index', '--'+flag, 'base.txt');
  await writeFile(join(repo, 'base.txt'), 'UNCOMMITTED SOURCE\n');
  assert.equal(git(repo, 'status', '--porcelain=v1', '--untracked-files=all'), '');
  const a = await manager.allocate(repo, 'child');
  assert.equal(await readFile(join(a.path, 'base.txt'), 'utf8'), 'base\n');
  git(a.path, 'update-index', '--'+flag, 'other.txt');
  await writeFile(join(a.path, 'other.txt'), 'UNCOMMITTED CHILD\n');
  const snapshot = execFileSync(process.execPath,
    [join(dev, 'skills/dynamic-workflows/recipes/implementation-review/snapshot.mjs')],
    {cwd:a.path, encoding:'utf8'});
  const output = await manager.commit(a);
  assert.equal(output.head, a.base);
  assert.equal(snapshot, 'git-tree:'+git(a.path, 'rev-parse', 'HEAD^{tree}'));
  assert.equal(git(a.path, 'show', 'HEAD:other.txt'), 'other');
  assert.equal(await readFile(join(a.path, 'other.txt'), 'utf8'), 'UNCOMMITTED CHILD\n');
  git(a.path, 'update-index', '--no-'+flag, 'other.txt');
  await writeFile(join(a.path, 'other.txt'), 'other\n');
  await writeFile(join(a.path, 'new.txt'), 'NEW\n');
  const source = await manager.commit(a);
  await manager.integrate(repo, [source], [source]);
  assert.equal(await readFile(join(repo, 'base.txt'), 'utf8'), 'UNCOMMITTED SOURCE\n');
  assert.equal(git(repo, 'show', 'HEAD:base.txt'), 'base');
  git(repo, 'update-index', '--no-'+flag, 'base.txt');
  await assert.rejects(manager.allocate(repo, 'negative-control'), /must be clean/);
  console.log(JSON.stringify({id:'r06-B02', flag, hiddenDirtyAllocationAccepted:true,
    childCommitOmittedChange:true, snapshotOmittedChange:true,
    hiddenDirtyIntegrationAccepted:true, visibleDirtyRejected:true}));
}
